with cleaned as (select *, date_format(paid_at, 'MMM yyyy') as paid_at_label from payments where paid_at >= date '2023-07-30' and order_id is not null), flagged as (select *, case when lag(paid_at) over (partition by status order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by status order by paid_at, id) + interval 7 days then 1 else 0 end as is_new_session from cleaned), sessions_payments as (select *, sum(is_new_session) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as burst_id from flagged) select date_trunc('month', paid_at) as activity_month, case when burst_id >= 9 then 'HIGH' else 'LOW' end as burst_id_tier, count_if(method = 'paypal') as paypal_events, min(paid_at) as first_seen, size(collect_set(method)) as num_methods from sessions_payments group by date_trunc('month', paid_at), case when burst_id >= 9 then 'HIGH' else 'LOW' end having size(collect_set(method)) > 1 order by num_methods desc nulls last;
